// 1) Verify the store's HMAC signature on the raw body before trusting anything.
const crypto = require('crypto');
const cfg = $('Config').first().json;
const item = $('Webhook: store order paid (Shopify / WooCommerce / Salla)').first();
const headers = item.json.headers || {};
const raw = item.binary?.data ? Buffer.from(item.binary.data.data, 'base64').toString() : JSON.stringify(item.json.body || {});
const expected = crypto.createHmac('sha256', cfg.webhook_secret).update(raw).digest('base64');
const given = headers['x-shopify-hmac-sha256'] || headers['x-sample-hmac'] || '';
if (given !== expected) throw new Error('Webhook signature mismatch, request dropped');
const o = item.json.body || JSON.parse(raw);

// 2) Normalise EVERY line, not only the first. An order with three products is
//    three lines on one purchase order, one label and one email.
const map = JSON.parse(cfg.sku_map);
const lines = (o.line_items || []).map(li => ({
  title: li.title || '',
  sku: li.sku || map[li.title] || '',
  qty: Number(li.quantity || 1),
}));
const unmapped = lines.filter(l => !l.sku).map(l => l.title || '(untitled line)');
if (!lines.length) throw new Error('Order has no line items');

const email = String(o.email || o.customer?.email || '').toLowerCase().trim();
const phone = String(o.phone || o.customer?.phone || o.shipping_address?.phone || '').trim();

const order = {
  order_id: 'SH-' + (o.order_number || o.id), channel: o.channel || 'Shopify',
  customer: [o.customer?.first_name, o.customer?.last_name].filter(Boolean).join(' ') || o.customer?.name || 'Unknown',
  email, phone,
  // How to tell the customer. No email is not a reason to refuse the order;
  // the goods still ship, the message goes by SMS, and with neither we tell ops.
  contact_channel: email ? 'email' : (phone ? 'sms' : ''),
  contact_to: email || phone || '',
  lines, unmapped,
  products: lines.map(l => l.qty + ' x ' + l.title).join(', '),
  // Kept for anything that still reads the old single fields.
  product: lines[0].title, sku: lines[0].sku, qty: lines[0].qty,
  amount: Number(o.total_price || 0),
  ship_to: o.shipping_address || {}, base: cfg.base, received_at: new Date().toISOString(),
};

// 3) Idempotency: has this order id already been COMPLETED. It is marked in
//    "Respond to webhook", after the work, so an attempt that fails half way
//    is retried by the store instead of being skipped as a duplicate.
const seen = $getWorkflowStaticData('global'); seen.orders = seen.orders || {};
order.duplicate = !!seen.orders[order.order_id];
return [{ json: order }];

const o = $('Verify HMAC, normalise, idempotency').first().json;
let stock = null; try { stock = $('Supplier API: stock check').first().json; } catch (e) {}
let tracking = null; try { tracking = $('Shipping API: create label + tracking').first().json.tracking; } catch (e) {}
const route = o.unmapped.length ? 'held' : (stock && stock.ok ? 'fulfilled' : 'backorder');

// Only now is the order marked as handled. A run that died before this line
// leaves the id unmarked, so the store's retry does the work.
const seen = $getWorkflowStaticData('global'); seen.orders = seen.orders || {};
seen.orders[o.order_id] = Date.now();

return [{ json: {
  ok: true, order_id: o.order_id, route, lines: o.lines.length, tracking,
  lead_days: stock ? stock.lead_days : null,
  note: o.unmapped.length ? 'not ordered, unmapped product: ' + o.unmapped.join(', ') : (o.contact_channel ? '' : 'customer has no email or phone, ops told'),
} }];

// The ERP may answer with one object holding an items array, or with one item
// per SKU when n8n splits a bare array. Reading only .items reported "all
// above threshold" on the second shape, which is the silent kind of wrong.
const first = $input.first().json || {};
const rows = Array.isArray(first.items) ? first.items : $input.all().map(i => i.json);
const items = rows.filter(r => r && r.sku !== undefined && r.sku !== null && String(r.sku) !== '');
const low = items.filter(i => Number(i.qty) <= 5);
return [{ json: {
  checked: items.length,
  low_stock: low,
  text: !items.length ? 'Inventory sync: nothing came back from the ERP, check the connection'
      : low.length ? 'Low stock: ' + low.map(i => i.sku + '=' + i.qty).join(', ')
      : 'All SKUs above threshold',
} }];
